using Cultivation.Domain;
using Cultivation.Simulation;
using Cultivation.Persistence;
internal static class R2PartyHuntTests
{
    private static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
    private static WorldState World(){var w=LifeEventScenario.Create();w.SectDuty=null;WorldPeriodFixture.Reset(w);for(int n=0;n<w.Characters.Count;n++)if(w.Characters[n].Id is "player" or "npc:00"){var a=w.Characters[n];w.Characters[n]=a with {DemoLocationId="sect",HexPosition=RegionGeometry.Resolve(w.HexMap!,a,"sect"),Health=100};}w.Hunts.Add(new("r2-hunt","sect",MonsterKind.Wolf,5,10,20,0,[]));return w;}
    private static ActionIntent Cmd(string id,string actor,ActionKind kind,string target,string item="party")=>new(id,actor,target,item,1,0,actor=="player"?DecisionSource.Player:DecisionSource.Npc,kind);
    public static IEnumerable<(string Name,Action Body)> Cases=>new (string,Action)[]{
        ("R2 party invite and acceptance preserve voluntary membership",()=>{var e=new SimulationEngine(World());var invite=Cmd("invite","player",ActionKind.InviteParty,"npc:00");e.Submit(invite);e.AdvanceTo(0);var w=e.Snapshot();var a=w.Time!.ActionRuntime!.Actions[invite.Id];Check(a.Phase==ActionPhase.Running&&!w.PartyInvitations.Any(v=>v.Id==invite.Id),"Invitation applied early");e.AdvanceTo(a.DueAt);w=e.Snapshot();Check(w.Time!.ActionRuntime!.Actions[invite.Id].Phase==ActionPhase.Completed&&w.PartyInvitations.Single(v=>v.Id==invite.Id).Status==PartyInviteStatus.Pending,"Invitation failed");var accept=Cmd("accept","npc:00",ActionKind.AcceptParty,invite.Id);e.Submit(accept);e.AdvanceTo(a.DueAt);w=e.Snapshot();long due=w.Time!.ActionRuntime!.Actions[accept.Id].DueAt;e.AdvanceTo(due);w=e.Snapshot();Check(w.Time!.ActionRuntime!.Actions[accept.Id].Phase==ActionPhase.Completed&&w.Parties.Single(p=>p.Id==invite.Id).Members.Contains("npc:00"),"Acceptance failed");}),
        ("R2 hunt acceptance survives JSON and SQLite without duplicate",()=>{var e=new SimulationEngine(World());var i=Cmd("hunt","player",ActionKind.AcceptHunt,"r2-hunt","combat");e.Submit(i);e.AdvanceTo(0);var w=e.Snapshot();var a=w.Time!.ActionRuntime!.Actions[i.Id];Check(!w.Hunts.Single(h=>h.Id=="r2-hunt").Participants.Contains("player"),"Hunt accepted early");string dir=Path.Combine(Path.GetTempPath(),"r2-hunt-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);try{foreach(IWorldStore store in new IWorldStore[]{new JsonWorldStore(),new SqliteWorldStore()}){string p=Path.Combine(dir,store.GetType().Name);store.Save(p,w);var x=new SimulationEngine(w);var y=new SimulationEngine(store.Load(p));x.AdvanceTo(a.DueAt);y.AdvanceTo(a.DueAt);var d=y.Snapshot();Check(WorldCodec.Digest(x.Snapshot())==WorldCodec.Digest(d)&&d.Time!.ActionRuntime!.Actions[i.Id].Phase==ActionPhase.Completed&&d.Hunts.Single(h=>h.Id=="r2-hunt").Participants.Count(id=>id=="player")==1,"Hunt continuation wrong");}}finally{foreach(string p in Directory.GetFiles(dir))File.Delete(p);Directory.Delete(dir);}}),
        ("R2 party acceptance at invitation expiry fails without AP refund",()=>{var e=new SimulationEngine(World());Check(e.ExecutePlayerActivity(Cmd("invite-expiry","player",ActionKind.InviteParty,"npc:00")).Accepted,"Invite failed");var w=e.Snapshot();long expiry=w.PartyInvitations.Single(v=>v.Id=="invite-expiry").ExpiresAtSeconds!.Value;e.AdvanceTo(expiry-600);var i=Cmd("late-accept","npc:00",ActionKind.AcceptParty,"invite-expiry");e.Submit(i);e.AdvanceTo(expiry-600);w=e.Snapshot();Check(w.Time!.ActionRuntime!.Actions[i.Id].Phase==ActionPhase.Running,"Acceptance not started");e.AdvanceTo(expiry);w=e.Snapshot();Check(w.Time!.ActionRuntime!.Actions[i.Id].Phase==ActionPhase.Failed&&!w.Parties.Any(p=>p.Id=="invite-expiry")&&w.Time.Charges.Count(c=>c.ActionId==i.Id)==1,"Expired acceptance succeeded or AP changed");})
    };
}
